@dataclass(frozen=True)
class AugmentParams:
    """Probabilities and strengths for the optional (non-affine) augmentations.

    All probabilities default to 0.0, so callers that do not pass an
    AugmentParams keep the plain benanne behaviour (affine + colour only).
    train.py builds one of these from Config when extra augmentation is enabled.
    """
    cutout_prob: float = 0.0
    cutout_n_holes: int = 2
    cutout_max_size_ratio: float = 0.20
    poisson_prob: float = 0.0
    poisson_scale: float = 25.0
    blur_prob: float = 0.0
    blur_sigma_range: Tuple[float, float] = (0.5, 2.0)


COLOUR_CHANNEL_WEIGHTS = tf.constant(
    [-0.0148366, -0.01253134, -0.01040762],
    dtype=tf.float32,
)


# ══════════════════════════════════════════════════════════════
# LABEL DETERMINATION (Regression - 37 Targets)
# ══════════════════════════════════════════════════════════════

def generate_labels_df(solutions_csv: Path, image_dir: Path) -> pd.DataFrame:
    """Generate 37-target DataFrame from Galaxy Zoo solutions CSV for Regression."""
    df = pd.read_csv(solutions_csv)

    # Automatically extract all 37 Class probability columns
    target_cols = [col for col in df.columns if col.startswith('Class')]
    if len(target_cols) != 37:
        print(f"WARNING: Expected 37 Class columns, found {len(target_cols)}")

    df['image_path'] = df['GalaxyID'].astype(str).apply(lambda gid: str(image_dir / f'{gid}.jpg'))

    # Check physical file existence to prune missing downloads
    df = df[df['image_path'].apply(lambda p: Path(p).exists())].copy()

    keep_cols = ['GalaxyID', 'image_path'] + target_cols
    return df[keep_cols], target_cols


# ══════════════════════════════════════════════════════════════
# IMAGE LOADING & BASE PREPROCESSING
# ══════════════════════════════════════════════════════════════

def _smart_crop(image: tf.Tensor, ratio: float = 0.75) -> tf.Tensor:
    """Crops the image around its brightness centroid instead of the static center.

    Uses a Gaussian center prior to avoid latching onto background stars.
    """
    # A ratio >= 1.0 keeps the whole image, so the centroid math below is pure
    # wasted compute (a full-image meshgrid + Gaussian per image, per epoch).
    # The active config uses center_crop_ratio=1.0, so short-circuit here.
    if ratio >= 1.0:
        return image

    shape = tf.shape(image)
    h_int, w_int = shape[0], shape[1]
    h, w = tf.cast(h_int, tf.float32), tf.cast(w_int, tf.float32)

    # Calculate centroid using green channel (brightness approximation)
    img_green = image[..., 1]

    # Apply Gaussian center prior (sigma^2 = 5000 as in benanne solution)
    yy_grid, xx_grid = tf.meshgrid(tf.range(h_int), tf.range(w_int), indexing='ij')
    yy_grid = tf.cast(yy_grid, tf.float32)
    xx_grid = tf.cast(xx_grid, tf.float32)

    prior = tf.exp(-((yy_grid - h/2.0)**2 + (xx_grid - w/2.0)**2) / 5000.0)
    img_weighted = img_green * prior

    total_flux = tf.reduce_sum(img_weighted) + 1e-6

    # Weighted average coordinates
    cy = tf.reduce_sum(tf.reduce_sum(img_weighted, axis=1) * tf.cast(tf.range(h_int), tf.float32)) / total_flux
    cx = tf.reduce_sum(tf.reduce_sum(img_weighted, axis=0) * tf.cast(tf.range(w_int), tf.float32)) / total_flux

    # Clip centroid to keep the crop mostly within image bounds
    cy = tf.clip_by_value(cy, h * 0.1, h * 0.9)
    cx = tf.clip_by_value(cx, w * 0.1, w * 0.9)

    # Crop size
    ch = tf.cast(h * ratio, tf.int32)
    cw = tf.cast(w * ratio, tf.int32)

    offset_h = tf.cast(cy - tf.cast(ch, tf.float32) / 2.0, tf.int32)
    offset_w = tf.cast(cx - tf.cast(cw, tf.float32) / 2.0, tf.int32)

    # Final clamping to ensure valid crop
    offset_h = tf.clip_by_value(offset_h, 0, h_int - ch)
    offset_w = tf.clip_by_value(offset_w, 0, w_int - cw)

    return tf.image.crop_to_bounding_box(image, offset_h, offset_w, ch, cw)


def load_and_preprocess_image(path: tf.Tensor, label: tf.Tensor, image_size: int,
                               center_crop_ratio: float = 0.75):
    img = tf.io.read_file(path)
    img = tf.image.decode_jpeg(img, channels=3)
    img = tf.cast(img, tf.float32)
    img = _smart_crop(img, ratio=center_crop_ratio)
    img = tf.image.resize(img, [image_size, image_size])
    img = tf.clip_by_value(img, 0.0, 255.0)
    return img, label


# ══════════════════════════════════════════════════════════════
# AUGMENTATION
# ══════════════════════════════════════════════════════════════

def apply_cutout(image: tf.Tensor, n_holes: int = 2, max_size_ratio: float = 0.20) -> tf.Tensor:
    shape = tf.shape(image)
    h, w = shape[0], shape[1]
    img_mean = tf.reduce_mean(image)

    mask = tf.ones_like(image)
    for _ in range(n_holes):
        hole_size_h = tf.random.uniform([], minval=tf.cast(tf.cast(h, tf.float32) * 0.05, tf.int32),
                                         maxval=tf.maximum(tf.cast(tf.cast(h, tf.float32) * max_size_ratio, tf.int32), 2),
                                         dtype=tf.int32)
        hole_size_w = tf.random.uniform([], minval=tf.cast(tf.cast(w, tf.float32) * 0.05, tf.int32),
                                         maxval=tf.maximum(tf.cast(tf.cast(w, tf.float32) * max_size_ratio, tf.int32), 2),
                                         dtype=tf.int32)
        cy = tf.random.uniform([], minval=hole_size_h // 2, maxval=h - hole_size_h // 2, dtype=tf.int32)
        cx = tf.random.uniform([], minval=hole_size_w // 2, maxval=w - hole_size_w // 2, dtype=tf.int32)

        y1 = tf.maximum(cy - hole_size_h // 2, 0)
        y2 = tf.minimum(cy + hole_size_h // 2, h)
        x1 = tf.maximum(cx - hole_size_w // 2, 0)
        x2 = tf.minimum(cx + hole_size_w // 2, w)

        top_pad = y1
        bottom_pad = h - y2
        left_pad = x1
        right_pad = w - x2
        hole_h = y2 - y1
        hole_w = x2 - x1

        hole = tf.zeros([hole_h, hole_w, 3])
        hole = tf.pad(hole, [[top_pad, bottom_pad], [left_pad, right_pad], [0, 0]], constant_values=1.0)
        mask = mask * hole

    image = image * mask + img_mean * (1.0 - mask)
    return image


def apply_poisson_noise(image: tf.Tensor, scale: float = 25.0) -> tf.Tensor:
    img_norm = image / 255.0
    img_scaled = img_norm * scale
    noisy = tf.random.poisson(shape=[], lam=tf.maximum(img_scaled, 1e-6))
    noisy = noisy / scale * 255.0
    return tf.clip_by_value(noisy, 0.0, 255.0)


def apply_gaussian_blur(image: tf.Tensor, sigma: float = 1.0) -> tf.Tensor:
    kernel_size = tf.cast(tf.math.ceil(sigma * 3.0) * 2 + 1, tf.int32)
    kernel_size = tf.maximum(kernel_size, 3)
    half = tf.cast(kernel_size // 2, tf.float32)
    x = tf.range(-half, half + 1, dtype=tf.float32)
    kernel_1d = tf.exp(-x ** 2 / (2.0 * sigma ** 2))
    kernel_1d = kernel_1d / tf.reduce_sum(kernel_1d)
    kernel_2d = tf.tensordot(kernel_1d, kernel_1d, axes=0)
    kernel_2d = kernel_2d[:, :, tf.newaxis, tf.newaxis]
    kernel_2d = tf.tile(kernel_2d, [1, 1, 3, 1])

    image_4d = tf.expand_dims(image, 0)
    blurred = tf.nn.depthwise_conv2d(image_4d, kernel_2d, strides=[1, 1, 1, 1], padding='SAME')
    return tf.squeeze(blurred, 0)


def apply_affine_transform(
    image: tf.Tensor,
    angle: tf.Tensor,
    zoom: tf.Tensor = tf.constant(1.0, dtype=tf.float32),
    translate_x: tf.Tensor = tf.constant(0.0, dtype=tf.float32),
    translate_y: tf.Tensor = tf.constant(0.0, dtype=tf.float32),
    flip_left_right: tf.Tensor = tf.constant(False),
) -> tf.Tensor:
    """Apply a deterministic affine transform in the style of benanne's pipeline."""
    image = tf.cond(flip_left_right, lambda: tf.image.flip_left_right(image), lambda: image)

    cos_a = tf.cos(angle) / zoom
    sin_a = tf.sin(angle) / zoom
    h = tf.cast(tf.shape(image)[0], tf.float32)
    w = tf.cast(tf.shape(image)[1], tf.float32)
    cx = (w - 1.0) / 2.0
    cy = (h - 1.0) / 2.0

    a0 = cos_a
    a1 = sin_a
    a2 = cx - a0 * cx - a1 * cy + translate_x
    b0 = -sin_a
    b1 = cos_a
    b2 = cy - b0 * cx - b1 * cy + translate_y

    transform = tf.reshape(tf.stack([a0, a1, a2, b0, b1, b2, 0.0, 0.0]), [1, 8])
    image_4d = tf.expand_dims(image, 0)
    transformed = tf.raw_ops.ImageProjectiveTransformV3(
        images=image_4d,
        transforms=tf.cast(transform, tf.float32),
        output_shape=tf.shape(image)[:2],
        fill_value=0.0,
        interpolation='BILINEAR',
        fill_mode='REFLECT',
    )
    return tf.squeeze(transformed, 0)


def apply_colour_perturbation(image: tf.Tensor, std: float = 0.5) -> tf.Tensor:
    image = image / 255.0
    alpha = tf.random.normal([], stddev=std, dtype=tf.float32)
    image = tf.clip_by_value(image + alpha * COLOUR_CHANNEL_WEIGHTS, 0.0, 1.0)
    return image * 255.0


def _maybe_apply(image: tf.Tensor, prob: float, fn) -> tf.Tensor:
    """Apply ``fn`` to ``image`` with the given probability.

    ``prob`` is a Python float known at graph-build time, so a probability of
    0.0 is short-circuited without emitting a tf.cond at all.
    """
    if prob <= 0.0:
        return image
    return tf.cond(tf.random.uniform([]) < prob, lambda: fn(image), lambda: image)


def augment_image(image: tf.Tensor, label: tf.Tensor, params: AugmentParams | None = None):
    h = tf.cast(tf.shape(image)[0], tf.float32)
    w = tf.cast(tf.shape(image)[1], tf.float32)
    scale_x = w / 424.0
    scale_y = h / 424.0

    angle = tf.random.uniform([], 0.0, 2.0 * math.pi)
    log_zoom = tf.random.uniform([], math.log(1.0 / 1.3), math.log(1.3))
    zoom = tf.exp(log_zoom)
    translate_x = tf.random.uniform([], -4.0, 4.0) * scale_x
    translate_y = tf.random.uniform([], -4.0, 4.0) * scale_y
    flip_left_right = tf.random.uniform([]) > 0.5

    image = apply_affine_transform(
        image,
        angle=angle,
        zoom=zoom,
        translate_x=translate_x,
        translate_y=translate_y,
        flip_left_right=flip_left_right,
    )

    # Optional astronomy-flavoured augmentations, each gated by its probability.
    # These are no-ops unless an AugmentParams with non-zero probabilities is
    # passed in (train.py wires this from Config when extra augmentation is on).
    if params is not None:
        image = _maybe_apply(
            image, params.poisson_prob,
            lambda im: apply_poisson_noise(im, params.poisson_scale),
        )

        def _blur(im: tf.Tensor) -> tf.Tensor:
            sigma = tf.random.uniform(
                [], params.blur_sigma_range[0], params.blur_sigma_range[1]
            )
            return apply_gaussian_blur(im, sigma)

        image = _maybe_apply(image, params.blur_prob, _blur)

    image = apply_colour_perturbation(image, std=0.5)

    if params is not None:
        image = _maybe_apply(
            image, params.cutout_prob,
            lambda im: apply_cutout(im, params.cutout_n_holes, params.cutout_max_size_ratio),
        )

    image = tf.clip_by_value(image, 0.0, 255.0)
    return image, label


def apply_tta_transform(image: tf.Tensor, label: tf.Tensor, tta_index: int):
    """Apply deterministic benanne-style TTA: 10 rotations x 3 zooms x 2 flips."""
    zooms = (1.0, 1.0 / 1.2, 1.2)
    zoom_index = (tta_index // 20) % len(zooms)
    transform_index = tta_index % 20
    angle_index = transform_index // 2
    flip_left_right = tf.equal(transform_index % 2, 1)
    angle = tf.cast(angle_index, tf.float32) * (2.0 * math.pi / 10.0)

    image = apply_affine_transform(
        image,
        angle=angle,
        zoom=tf.constant(zooms[zoom_index], dtype=tf.float32),
        flip_left_right=flip_left_right,
    )
    return image, label


# ══════════════════════════════════════════════════════════════
# DATASET BUILDERS
# ══════════════════════════════════════════════════════════════

def build_dataset(
    image_paths: np.ndarray,
    labels: np.ndarray,
    image_size: int,
    batch_size: int,
    center_crop_ratio: float = 0.75,
    augment: bool = False,
    shuffle: bool = False,
    cache: bool = False,
    drop_remainder: bool = False,
    tta_index: int | None = None,
    aug_params: AugmentParams | None = None,
) -> tf.data.Dataset:
    """Build a tf.data.Dataset mapping paths and 37-node target vectors."""
    if augment and tta_index is not None:
        raise ValueError("Training augmentation and deterministic TTA are mutually exclusive.")

    ds = tf.data.Dataset.from_tensor_slices((image_paths, labels))
    ds = ds.map(
        lambda p, y: load_and_preprocess_image(p, y, image_size, center_crop_ratio),
        num_parallel_calls=tf.data.AUTOTUNE,
    )

    if shuffle:
        ds = ds.shuffle(buffer_size=min(len(image_paths), 10000), reshuffle_each_iteration=True)

    if augment:
        ds = ds.map(lambda i, l: augment_image(i, l, aug_params), num_parallel_calls=tf.data.AUTOTUNE)

    if tta_index is not None:
        ds = ds.map(
            lambda i, l: apply_tta_transform(i, l, tta_index),
            num_parallel_calls=tf.data.AUTOTUNE,
        )

    if cache:
        ds = ds.cache()

    ds = ds.batch(batch_size, drop_remainder=drop_remainder).prefetch(tf.data.AUTOTUNE)
    return ds


def build_tta_dataset(
    image_paths: np.ndarray,
    image_size: int,
    batch_size: int,
    n_augments: int,
    center_crop_ratio: float = 0.75,
) -> tf.data.Dataset:
    """Decode each image once and emit all `n_augments` deterministic TTA variants.

    Variants are streamed in image-major, augment-minor order:
    ``[img0_tta0, img0_tta1, ..., img0_tta{k-1}, img1_tta0, ...]``. Predicting
    over this dataset and reshaping to ``(num_images, n_augments, -1)`` then
    averaging over axis 1 reproduces the mean-over-TTA-passes result — but each
    JPEG is read and decoded a single time instead of once per pass, which is
    the dominant cost of test-time augmentation over large image sets.
    """
    dummy_label = tf.zeros([37], dtype=tf.float32)

    def _load_variants(path):
        image, _ = load_and_preprocess_image(path, dummy_label, image_size, center_crop_ratio)
        # apply_tta_transform requires a Python int index (it indexes a Python
        # list of zoom factors), so the variants are unrolled in a Python loop.
        variants = [apply_tta_transform(image, dummy_label, i)[0] for i in range(n_augments)]
        return tf.stack(variants, axis=0)  # (n_augments, H, W, 3)

    ds = tf.data.Dataset.from_tensor_slices(image_paths)
    # Modest fixed parallelism: each element holds n_augments full-size images,
    # so bound how many are in flight at once to keep memory predictable.
    ds = ds.map(_load_variants, num_parallel_calls=4)
    ds = ds.unbatch()
    ds = ds.batch(batch_size).prefetch(tf.data.AUTOTUNE)
    return ds


# ══════════════════════════════════════════════════════════════
# SPLITTING & ORCHESTRATION
# ══════════════════════════════════════════════════════════════

def build_datasets(labels_df: pd.DataFrame, config: Config):
    """Build train/validation/test splits for regression."""
    if config.legacy_ordered_split:
        ordered_df = labels_df.sort_values('GalaxyID').reset_index(drop=True)
        train_fraction = 1.0 - config.val_split - config.test_split
        train_end = int(len(ordered_df) * train_fraction)
        val_end = int(len(ordered_df) * (1.0 - config.test_split))
        train_df = ordered_df.iloc[:train_end].reset_index(drop=True)
        val_df = ordered_df.iloc[train_end:val_end].reset_index(drop=True)
        test_df = ordered_df.iloc[val_end:].reset_index(drop=True)
    else:
        train_df, temp_df = train_test_split(
            labels_df,
            test_size=config.val_split + config.test_split,
            random_state=config.seed,
        )
        if config.test_split > 0:
            test_ratio_of_temp = config.test_split / (config.val_split + config.test_split)
            val_df, test_df = train_test_split(
                temp_df,
                test_size=test_ratio_of_temp,
                random_state=config.seed,
            )
        else:
            val_df = temp_df
            test_df = temp_df.iloc[0:0].copy()

        train_df = train_df.reset_index(drop=True)
        val_df = val_df.reset_index(drop=True)
        test_df = test_df.reset_index(drop=True)

    split_info = {
        'train_size': len(train_df),
        'val_size': len(val_df),
        'test_size': len(test_df),
        'total_labeled_images': len(labels_df),
    }

    return split_info, (train_df, val_df, test_df)


